describe('Data Table Row and Column Verification', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/tables');
  });

  it('should display table with correct header and row count', () => {
    // Verify table exists
    cy.get('[data-testid="#table1"]').should('be.visible');

    // Verify table has header row
    cy.get('[data-testid="#table1"]').find('thead').should('be.visible');

    // Verify header row contains correct column headings
    cy.get('[data-testid="#table1"]').find('thead th').should('have.length', 4);
    cy.get('[data-testid="#table1"]').find('thead th').eq(0).should('contain', 'Last Name');
    cy.get('[data-testid="#table1"]').find('thead th').eq(1).should('contain', 'First Name');
    cy.get('[data-testid="#table1"]').find('thead th').eq(2).should('contain', 'Email');
    cy.get('[data-testid="#table1"]').find('thead th').eq(3).should('contain', 'Due');

    // Verify table body contains 4 data rows
    cy.get('[data-testid="#table1"]').find('tbody tr').should('have.length', 4);

    // Verify first row has correct data
    cy.get('[data-testid="#table1"]').find('tbody tr').eq(0).should('be.visible');
    cy.get('[data-testid="#table1"]').find('tbody tr').eq(0).find('td').eq(0).should('contain', 'Smith');
    cy.get('[data-testid="#table1"]').find('tbody tr').eq(0).find('td').eq(1).should('contain', 'John');
    cy.get('[data-testid="#table1"]').find('tbody tr').eq(0).find('td').eq(2).should('contain', 'john@example.com');
    cy.get('[data-testid="#table1"]').find('tbody tr').eq(0).find('td').eq(3).should('contain', '2023-01-15');
  });

  it('should verify specific row data and column alignment', () => {
    // Verify table exists
    cy.get('[data-testid="#table1"]').should('be.visible');

    // Verify table has 4 rows
    cy.get('[data-testid="#table1"]').find('tbody tr').should('have.length', 4);

    // Verify the row with email 'jsmith@gmail.com' exists
    cy.get('[data-testid="#table1"]').find('tbody tr').each(($row) => {
      cy.wrap($row).within(() => {
        cy.get('td').eq(2).should('contain', 'jsmith@gmail.com');
      });
    });

    // Verify the row with email 'jsmith@gmail.com' has correct last name and first name
    cy.get('[data-testid="#table1"]').find('tbody tr').each(($row) => {
      cy.wrap($row).within(() => {
        cy.get('td').eq(2).should('contain', 'jsmith@gmail.com');
        cy.get('td').eq(0).should('contain', 'Smith');
        cy.get('td').eq(1).should('contain', 'Jane');
        cy.get('td').eq(3).should('contain', '2023-02-20');
      });
    });

    // Verify all rows have 4 columns
    cy.get('[data-testid="#table1"]').find('tbody tr').each(($row) => {
      cy.wrap($row).should('have.length', 4);
    });
  });
});
